const h = $json.headers || {};
const token = h['x-symbalyx-token'] || h['X-Symbalyx-Token'] || '';
const expected = $env.SYMBALYX_WEBHOOK_SECRET || '';
if (!expected) return [{ json: { _ok:false, _status:500, _error:'SYMBALYX_WEBHOOK_SECRET not configured' } }];
if (token !== expected) return [{ json: { _ok:false, _status:401, _error:'invalid_token' } }];
const b = $json.body || {};
const bcl_id = String(b.bcl_id || '').trim();
const new_assignee_id = String(b.new_assignee_id || '').trim();
const new_assigned_to = String(b.new_assigned_to || '').trim();
const decided_by = String(b.decided_by || '').trim();
const decider_id = String(b.decider_id || '').trim();
const reason = String(b.reason || '').trim();
if (!bcl_id) return [{ json: { _ok:false, _status:400, _error:'missing bcl_id' } }];
if (!new_assignee_id && !new_assigned_to) return [{ json: { _ok:false, _status:400, _error:'missing new_assignee_id or new_assigned_to' } }];
if (!decided_by) return [{ json: { _ok:false, _status:400, _error:'missing decided_by' } }];
return [{ json: { _ok:true, bcl_id, new_assignee_id, new_assigned_to, decided_by, decider_id, reason } }];

// Merge nouveau assignee dans la ligne existante (Read+Merge anti-wipe).
const inp = $('Auth & validate').first().json;
const rows = $input.all().map(i => i.json);
const row = rows.find(r => String(r.id) === String(inp.bcl_id));
if (!row) return [{ json: { _ok:false, _status:404, _error:'bcl_id not found: ' + inp.bcl_id } }];
const prev_assigned_to = row.assigned_to || '';
const prev_assignee_id = row.assignee_id || '';
const merged = {
  // Toutes les colonnes existantes (préservées)
  id: row.id,
  ts: row.ts || '',
  run_id: row.run_id || '',
  source_workflow: row.source_workflow || '',
  item_type: row.item_type || '',
  item_id: row.item_id || '',
  title: row.title || '',
  recommendation: row.recommendation || '',
  recommended_action: row.recommended_action || '',
  priority_score: row.priority_score || '',
  priority_level: row.priority_level || '',
  expected_impact: row.expected_impact || '',
  effort_level: row.effort_level || '',
  // Colonnes mises à jour
  assigned_to: inp.new_assigned_to || prev_assigned_to,
  assignee_id: inp.new_assignee_id || prev_assignee_id,
  requires_human_validation: row.requires_human_validation || '',
  decision_status: row.decision_status || '',
  decided_by: row.decided_by || '',
  decider_id: row.decider_id || '',
  decided_at: row.decided_at || '',
  notes: ((row.notes || '') + ` [reassigné de ${prev_assigned_to||'-'} à ${inp.new_assigned_to||inp.new_assignee_id} par ${inp.decided_by} le ${new Date().toISOString().slice(0,10)}${inp.reason ? ' · ' + inp.reason : ''}]`).slice(0, 1000)
};
return [{ json: { _ok:true, merged, prev_assigned_to, prev_assignee_id } }];
